def compute_regularization(model, inputs, outputs, targets, config):
    """Weight Smoothness Regularization (WSR) - simplified test.

    Only applies weight smoothness penalty to convolutional filters.
    Very small coefficient to ensure training works.
    """
    device = outputs.device
    epoch = config['epoch']
    total_epochs = config['total_epochs']

    # Base regularization strength (very small)
    lambda_base = 1e-6

    # Warm-up for first 10 epochs
    warmup_epochs = 10
    if epoch < warmup_epochs:
        progress = epoch / warmup_epochs
        lambda_scale = lambda_base * progress
    else:
        lambda_scale = lambda_base

    if lambda_scale < 1e-9:
        return torch.tensor(0.0, device=device)

    weight_penalties = []

    for name, param in model.named_parameters():
        if 'conv' in name and 'weight' in name and param.dim() == 4:
            out_c, in_c, kH, kW = param.shape
            penalty = 0.0

            # Horizontal smoothness
            if kW > 1:
                diff_h = param[:, :, :, 1:] - param[:, :, :, :-1]
                penalty = penalty + (diff_h ** 2).mean()

            # Vertical smoothness
            if kH > 1:
                diff_v = param[:, :, 1:, :] - param[:, :, :-1, :]
                penalty = penalty + (diff_v ** 2).mean()

            if penalty > 0:
                weight_penalties.append(penalty)

    if not weight_penalties:
        return torch.tensor(0.0, device=device)

    avg_penalty = torch.stack(weight_penalties).mean()
    return lambda_scale * avg_penalty
